//update gets the data from the URL
function validate()
{


var username = document.getElementById("usrname").value;
var password = document.getElementById("pass").value;
  var ciphertext = Aes.Ctr.encrypt($('#pass').val(), $('#pass').val(), 256);
var r=  Math.random().toString(36).substring(2); 
var unikey = Aes.Ctr.encrypt(pass,r, 256);
URL = document.URL;
URL1 = document.URL;
	URL = URL.replace("login.html", "") + "login/userdt";
	URL = URL + "?user=" + username + "&pas=" + ciphertext + "&unky=" + unikey;

$.getJSON(URL, function(data){
var access_lvl =data["access"]

if (access_lvl == "admin"|| access_lvl == "operator")
{ 
alert("login sucessfully!!");

if (typeof(window.Storage) !== "undefined") 
{

sessionStorage.setItem("access_level", access_lvl);

}
 else {
// Sorry! No Web Storage support..
}
URL1 = URL1.replace("login.html", "") + "index.html";
window.location = URL1;
}
else {
alert("user or password incorrect!!!");
}

});

}



$(document).ready(function () {
    // encrypt listener
    $('#encryptBtn').click(function () {
        var t = new Date();
        var ciphertext = Aes.Ctr.encrypt($('#plaintext').val(), $('#password').val(), 256);
        $('#encrypt-time').html(((new Date() - t)) + 'ms');
        $('#cipher').val(ciphertext);
    });

    // decrypt listener
    $('#decryptBtn').click(function () {
        var t = new Date();
        var plain = Aes.Ctr.decrypt($('#cipher').val(), $('#password').val(), 256);
        $('#decrypt-time').html(((new Date() - t)) + 'ms');
        $('#plaintext').val(plain);
    });


    $('#plaintextDiv .clear').click(function () {
        $('#plaintext').val("");
    });
    $('#cipherDiv .clear').click(function () {
        $('#cipher').val("");
    });


});